// Post-build step for the llms.txt files generated by starlight-llms-txt.
//
// The plugin keeps links from page content as they appear in the HTML (`/docs/topics/graphql/`), which is
// useless to a tool that fetched llms-full.txt on its own. This rewrites every root-relative Markdown link
// and image URL to an absolute one on the deployed site, and separates a Starlight <LinkCard>'s link from its
// description (they render as `[Title](url)Description`). Fenced code blocks and inline code are left alone.
//
// Usage: node scripts/absolutize-llms-links.mjs [distDir]   (run after `astro build`; see package.json)

import { readdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const distDir = resolve(root, process.argv[2] ?? 'dist')

/** Read `site` from astro.config.mjs; fall back to the known value. */
async function siteOrigin() {
  const config = await readFile(join(root, 'astro.config.mjs'), 'utf8')
  const site = config.match(/^\s*site:\s*['"]([^'"]+)['"]/m)?.[1] ?? 'https://ghurijs.github.io'
  return new URL(site).origin
}

const origin = await siteOrigin()

/** `/docs/x/` -> `https://ghurijs.github.io/docs/x/`; protocol-relative `//host` is left as is. */
const absolutize = (url) => (url.startsWith('/') && !url.startsWith('//') ? origin + url : url)

// One pass over prose: an inline code span (left untouched) or an inline link/image with a root-relative URL,
// optionally in <angle brackets> and with a "title".
const INLINE =
  /(`+)[\s\S]*?(?<!`)\1(?!`)|(!?\[(?:[^[\]]|\[[^\]]*\])*\])\((<?)([^)\s>]*)(>?)((?:\s+"[^"]*")?)\)/g
// Reference definitions: `[label]: /docs/x/`.
const REFERENCE_DEF = /^(\s*\[[^\]]+\]:\s+<?)(\/[^\s>]*)/gm
// A LinkCard's description starts straight after the link, with no space.
const RUN_ON = /[\p{L}\p{N}]/u

let changedLinks = 0
let separatedCards = 0

function rewriteProse(text) {
  const out = text.replace(INLINE, (match, ticks, label, lt, url, gt, title, offset, whole) => {
    if (ticks) return match
    const next = absolutize(url)
    if (next !== url) changedLinks++
    let link = `${label}(${lt}${next}${gt}${title})`
    if (!label.startsWith('!') && RUN_ON.test(whole[offset + match.length] ?? '')) {
      link += ': '
      separatedCards++
    }
    return link
  })
  return out.replace(REFERENCE_DEF, (_m, pre, url) => {
    changedLinks++
    return pre + absolutize(url)
  })
}

/** Split into fenced code blocks (kept verbatim) and prose (rewritten). */
function rewrite(source) {
  const lines = source.split('\n')
  const out = []
  let prose = []
  let fence = null // { char, length }
  const flushProse = () => {
    if (prose.length) out.push(rewriteProse(prose.join('\n')))
    prose = []
  }
  for (const line of lines) {
    const marker = line.match(/^\s*(`{3,}|~{3,})/)?.[1]
    if (fence) {
      out.push(line)
      if (marker && marker[0] === fence.char && marker.length >= fence.length && /^\s*[`~]+\s*$/.test(line)) {
        fence = null
      }
    } else if (marker) {
      flushProse()
      out.push(line)
      fence = { char: marker[0], length: marker.length }
    } else {
      prose.push(line)
    }
  }
  flushProse()
  return out.join('\n')
}

async function txtFiles(dir) {
  const files = []
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name)
    if (entry.isFile() && /^llms.*\.txt$/.test(entry.name)) files.push(path)
    if (entry.isDirectory() && entry.name === '_llms-txt') {
      for (const name of await readdir(path)) if (name.endsWith('.txt')) files.push(join(path, name))
    }
  }
  return files
}

const files = await txtFiles(distDir)
if (files.length === 0) {
  console.error(`absolutize-llms-links: no llms*.txt files in ${distDir}`)
  process.exit(1)
}
for (const file of files) {
  const source = await readFile(file, 'utf8')
  const next = rewrite(source)
  if (next !== source) await writeFile(file, next)
}
console.log(
  `absolutize-llms-links: ${changedLinks} links made absolute, ${separatedCards} link cards separated in ${files.length} files (${origin})`,
)
